action.code:
double minor = 0;
int r1 = 0, r2 = 0, c1 = 0, c2 = 0;
for (int i = 0; i < 3; ++i) {
    if (i == row) continue;
    r1 = r2;
    r2 = i;
}
for (int j = 0; j < 3; ++j) {
    if (j == col) continue;
    c1 = c2;
    c2 = j;
}
minor = m[r1][c1] * m[r2][c2] - m[r1][c2] * m[r2][c1];
return ((row + col) % 2 == 0) ? minor : -minor;

